  "\t\t\t\t\t\tj += 2",
  "\t\t\t\t\telseif d == quote then",
  "\t\t\t\t\t\tclosed = true",
  "\t\t\t\t\t\tbreak",
  "\t\t\t\t\telse",
  "\t\t\t\t\t\tname ..= d",
  "\t\t\t\t\t\tj += 1",
  "\t\t\t\t\tend",
