  "\tend",
  "\treturn nil",
  "end",
  "",
  "local function vector3From(value: any): Vector3",
  "\tif typeof(value) == \"Vector3\" then",
  "\t\treturn value",
  "\tend",
  "\tif type(value) == \"table\" then",
  "\t\tif value[1] ~= nil then",
  "\t\t\treturn Vector3.new(toNumber(value[1], \"x\"), toNumber(value[2], \"y\"), toNumber(value[3], \"z\"))",
  "\t\tend",
