  "\t\t\ttoNumber(field(value, \"x\", \"X\") or 0, \"x\"),",
  "\t\t\ttoNumber(field(value, \"y\", \"Y\") or 0, \"y\"),",
  "\t\t\ttoNumber(field(value, \"z\", \"Z\") or 0, \"z\")",
