  "\t\tif value[1] ~= nil then",
  "\t\t\treturn Vector2.new(toNumber(value[1], \"x\"), toNumber(value[2], \"y\"))",
  "\t\tend",
  "\t\treturn Vector2.new(toNumber(field(value, \"x\", \"X\") or 0, \"x\"), toNumber(field(value, \"y\", \"Y\") or 0, \"y\"))",
  "\tend",
  "\terror('Expected a Vector2 such as {\"type\":\"Vector2\",\"x\":0,\"y\":1} or [0,1]', 0)",
  "end",
  "",
  "local function color3From(value: any): Color3",
  "\tif typeof(value) == \"Color3\" then",
  "\t\treturn value",
  "\tend",
