  "\t\tlocal b = toNumber(value[3] or field(value, \"b\", \"B\") or 0, \"b\")",
  "\t\tif r > 1 or g > 1 or b > 1 then",
  "\t\t\treturn Color3.fromRGB(r, g, b)",
  "\t\tend",
  "\t\treturn Color3.new(r, g, b)",
  "\tend",
